const entries: Entry[] = [
{
 day: 10, media: 'co-op', slug: 'dez-melhores-games-cooperativos', category: 'games', byline: R, kind: 'opinion',
 title: '10 games cooperativos para jogar junto — e descobrir quem lava a louça virtual',
 excerpt: 'Da cozinha em crise à nave compartilhada, a seleção do SPN valoriza jogos que fazem da parceria uma parte da aventura.',
 context: 'Lista editorial de 10 de setembro. Ordem opinativa, considerando variedade, integração entre jogadores e proposta cooperativa. Modos e plataformas variam por título; não é um ranking de vendas.',
 source: s('EA · It Takes Two', 'https://www.ea.com/games/it-takes-two/it-takes-two'),
 sources: [s('EA · It Takes Two','https://www.ea.com/games/it-takes-two/it-takes-two'),s('Valve · Portal 2','https://store.steampowered.com/app/620/Portal_2/'),s('Team17 · Overcooked! 2','https://www.team17.com/news/the-a-z-of-overcooked-2'),s('ConcernedApe · Stardew Valley','https://store.steampowered.com/app/413150/Stardew_Valley/'),s('EA · Unravel Two','https://store.steampowered.com/app/1225570/Unravel_Two/'),s('Asteroid Base · Lovers in a Dangerous Spacetime','https://store.steampowered.com/app/252110/Lovers_in_a_Dangerous_Spacetime/'),s('Ubisoft · Rayman Legends','https://store.steampowered.com/app/242550/Rayman_Legends/'),s('Dotemu · Shredder’s Revenge','https://store.steampowered.com/app/1361510/Teenage_Mutant_Ninja_Turtles_Shredders_Revenge/'),s('EA · Split Fiction','https://store.steampowered.com/app/2001120/Split_Fiction/'),s('Team17 · Moving Out 2','https://www.team17.com/games/moving-out-2')],
 body: ['Jogar junto deveria significar mais do que duas pessoas olhando a mesma explosão. Nossa seleção privilegia propostas em que dividir tarefas, combinar movimentos ou resolver um problema faz sentido. É uma lista de opinião: o primeiro lugar não ganhou uma eleição universal, e sua amizade não precisa concordar com a urna do SPN.', 'Também vale combinar as regras antes do convite. Cooperativo local, jogo pela internet e acesso entre plataformas são coisas diferentes. Confira a versão que pretende usar e não transforme a noite de diversão em atendimento técnico. Abaixo, dez maneiras de compartilhar a aventura. O grito de “era para a esquerda!” fica por conta da casa.'],
 sections: [
 {title:'1. It Takes Two',source:0,paragraphs:['A história de Cody e May transforma parceria em estrutura de jogo. A razão do primeiro lugar é essa: a dupla pertence à proposta, em vez de entrar como visita. Bom ponto de partida para quem procura uma aventura a dois com identidade. A terapia do casal ganhou obstáculos; o controle não vem com certificado de conselheiro.']},
 {title:'2. Portal 2',source:1,paragraphs:['Os quebra-cabeças cooperativos colocam comunicação na frente da pressa. Dois portais e duas cabeças podem resolver o caminho — ou construir uma discussão elegantemente geométrica. Fica tão alto na lista por oferecer um tipo de cooperação que depende de entender o problema, sem confundir barulho com trabalho em equipe.']},
 {title:'3. Overcooked! 2',source:2,paragraphs:['Cozinhar sob pressão vira organização coletiva. A proposta rende um contraste delicioso entre tarefas simples e coordenação difícil. É a escolha para quem gosta de partidas agitadas e aceita rir do caos. Só não use o fracasso no restaurante virtual como argumento definitivo para dividir as tarefas da cozinha real.']},
 {title:'4. Stardew Valley',source:3,paragraphs:['A fazenda compartilhada abre espaço para planos diferentes dentro do mesmo lugar. Esse ritmo merece destaque: parceria também pode acontecer entre cultivo, exploração e rotina. Combinar objetivos ajuda mais do que fiscalizar cada minuto do outro. A plantação não precisa de uma gerente que mande mensagens às seis da manhã.']},
 {title:'5. Unravel Two',source:4,paragraphs:['Os Yarnys ligados pelo fio oferecem uma imagem clara de apoio mútuo. O cooperativo local funciona como parte da ideia de conexão que escolhemos valorizar nesta lista. É uma alternativa para quem quer uma aventura de plataforma em dupla. O laço é bonito; tentar resolver tudo puxando a outra pessoa raramente é.']},
 {title:'6. Split Fiction',source:8,paragraphs:['A aventura cooperativa junta mundos de ficção científica e fantasia. A mistura dá à dupla uma proposta diferente para explorar, por isso ocupa espaço entre escolhas mais antigas. Duas imaginações cabem no mesmo convite. O desafio adicional é decidir qual delas vai explicar o plano sem começar uma reunião interminável.']},
 {title:'7. Lovers in a Dangerous Spacetime',source:5,paragraphs:['Uma nave com tarefas para dividir faz da circulação da equipe o coração da brincadeira. A escolha recompensa a ideia de que ninguém precisa fazer tudo sozinho. Vale para quem gosta de coordenação em grupo e aceita mudar de função. Amor no título, planilha de bordo na prática: romance também exige logística.']},
 {title:'8. Rayman Legends',source:6,paragraphs:['A plataforma ganha companhia e um convite para dividir o caminho. Entra pela leveza da proposta e pelo espaço que dá a uma sessão coletiva de aventura. Não é preciso transformar cada salto em disputa de currículo. Às vezes, o melhor talento da equipe é continuar rindo depois que todo mundo caiu no mesmo buraco.']},
 {title:'9. Teenage Mutant Ninja Turtles: Shredder’s Revenge',source:7,paragraphs:['O combate em grupo traz as Tartarugas Ninja para uma proposta de pancadaria cooperativa. A escolha privilegia a energia de avançar junto, com uma identidade pop imediatamente reconhecível. Pizza depois da missão parece um bom acordo. Dividir os pedaços, contudo, pode exigir mais diplomacia do que enfrentar o Destruidor.']},
 {title:'10. Moving Out 2',source:9,paragraphs:['Transportar móveis vira um problema para resolver em equipe. Fecha a lista porque leva a cooperação para uma situação cotidiana que já nasce cheia de potencial cômico. A graça editorial dessa escolha é simples: até a mudança pode virar aventura. Na vida real, pedir “só uma ajudinha” ainda deveria vir acompanhado do tamanho do sofá.']},
 ],
},
{
 day:11,media:'spider-man',slug:'bilheteria-setembro-homem-aranha-the-dog-stars',category:'filmes',byline:R,kind:'data',
 title:'Homem-Aranha segura a bilheteria; The Dog Stars perde força no recorte americano',
 excerpt:'O fim de semana de 4 a 6 de setembro tem liderança de Brand New Day e queda de 64% para The Dog Stars. Arrecadação não é lucro.',
 context:'Dados de 4–6 de setembro de 2026, mercado doméstico dos EUA e Canadá, em dólares americanos. Não são receitas brasileiras, mundiais nem o fechamento de setembro.',
 source:s('Box Office Mojo · fim de semana 36 de 2026','https://www.boxofficemojo.com/weekend/2026W36/'),
 body:['Spider-Man: Brand New Day liderou o fim de semana de 4 a 6 de setembro no mercado dos Estados Unidos e Canadá, com US$ 18.178.872. O resultado representa queda de 19,3% sobre o período anterior e leva o acumulado doméstico a US$ 917.941.367. É liderança com fôlego; o uniforme pode estar amassado, mas ainda tem gente passando pela catraca.', 'The Odyssey aparece em segundo, com US$ 13.095.130, seguida por Coyote vs. Acme, com US$ 11.969.005. Mais abaixo, The Dog Stars arrecadou US$ 2.774.914 e caiu 64% em relação ao fim de semana anterior. Essa retração indica perda de público nesse recorte. Dizer que o filme está perdendo força é sustentado pelos números; decretar prejuízo financeiro exigiria conhecer custos e receitas que esta tabela não traz.', 'Bilheteria tem geografia, moeda e período. Comparar um acumulado de várias semanas com uma estreia como se fossem o mesmo teste produz uma manchete animada e uma análise bem torta. Nossa leitura separa arrecadação do fim de semana e total doméstico. O dinheiro contado aqui vem das salas americanas e canadenses; a reação do público brasileiro não pode ser inventada por tradução.', 'O placar favorece Homem-Aranha e pede atenção para a trajetória de The Dog Stars. Para falar em sucesso ou fracasso comercial completo, ainda seriam necessários orçamento, divulgação, mercados internacionais e divisão das receitas. A bilheteria conta uma história importante. Só não entrega, sozinha, o extrato bancário inteiro do estúdio.'],
},
{
 day:12,media:'oasis',slug:'oasis-documentario-reencontro-anos-90',category:'cultura-pop',byline:F,kind:'feature',
 title:'Oasis volta ao cinema e leva os anos 90 junto na bagagem',
 excerpt:'Don’t Look Back in Anger acompanha o reencontro dos Gallagher. O documentário oferece uma ponte entre o britpop e a memória de uma geração.',
 context:'Edição de 12 de setembro. A agenda oficial informa lançamento nos EUA em 11 de setembro; datas internacionais variam. Texto de contexto, sem avaliação de uma sessão do filme.',source:disney,
 body:['Oasis: Don’t Look Back in Anger chegou à data de lançamento anunciada para os cinemas americanos: 11 de setembro. O documentário acompanha a turnê de reunião Oasis Live ’25, com Liam e Noel Gallagher. A direção é de Dylan Southern e Will Lovelace, e Steven Knight aparece como criador do projeto. O reencontro ganhou uma nova tela; a nostalgia, como de costume, já estava na fila.', 'O interesse vai além de registrar uma banda outra vez no palco. Oasis carrega um vínculo forte com o pop britânico dos anos 90, período que continua funcionando como referência para repertório, atitude e identidade de fãs. Um documentário sobre esse retorno pode confrontar lembrança e presente. A promessa de acesso aos bastidores merece ser acompanhada, mas promessa de divulgação não substitui o que o filme efetivamente mostra.', 'Há uma diferença entre preservar uma época e tentar congelá-la. A primeira atitude deixa músicas e personagens conversarem com quem chegou depois. A segunda exige que todo mundo trate uma década como a última vez em que a humanidade soube produzir um refrão. Sou favorável à memória; a carteirinha de fiscal da juventude pode ficar na gaveta.', 'A pauta de hoje olha para essa continuidade cultural. A produção é da Magna Studios com Sony Music Vision, e a agenda citada se refere aos Estados Unidos. Quem procura uma sessão no Brasil deve consultar a programação local. O passado merece contexto, o presente merece uma informação correta, e os irmãos Gallagher já fornecem personalidade suficiente sem nossa ajuda.'],
},
{
 day:13,media:'marieta',slug:'marieta-severo-dom-de-iludir-tv-brasileira',category:'series-streaming',byline:R,kind:'feature',
 title:'Marieta Severo troca a sala de Nenê pelos segredos de Dom de Iludir',
 excerpt:'A nova série brasileira da Netflix reúne Marieta, Alice Wegmann e Nanda Costa. O anúncio lembra a força de rostos que atravessaram a TV aberta.',context:'Anúncio divulgado pela Netflix em 10 de setembro. A estreia está prevista para 2026, sem dia informado nessa fonte. O texto relaciona a novidade à carreira televisiva de Marieta.',source:netflix,
 sources:[netflix,s('Memória Globo · Marieta Severo','https://memoriaglobo.globo.com/perfil/marieta-severo/noticia/marieta-severo.ghtml')],
 body:['Marieta Severo está no centro de Dom de Iludir, nova série brasileira anunciada pela Netflix com Alice Wegmann e Nanda Costa. Na trama, ela interpreta a colecionadora de arte Lúcia Rossetti, cuja relação com a filha Maíra, vivida por Wegmann, é atravessada por tensões. Irina, personagem de Nanda, entra nesse universo de intrigas. A produção está prevista para 2026; o anúncio de 10 de setembro não informa uma data completa de estreia.', 'Para muita gente, Marieta também chega acompanhada da memória de Nenê, de A Grande Família. Esse reconhecimento é parte da potência da televisão aberta brasileira: personagens entram na conversa doméstica e continuam conhecidos fora de seu programa original. Mas uma atriz não precisa repetir a mesma sala para merecer atenção. O sofá muda; a experiência permanece.', 'O contraste entre a comédia familiar lembrada pelo público e o melodrama com suspense anunciado para a nova série é o ponto cultural desta pauta. A familiaridade pode abrir a porta para uma personagem diferente, sem definir antecipadamente a atuação. Não vamos distribuir elogios a episódios ainda não avaliados. A curiosidade basta, e já é uma senhora anfitriã.', 'A direção geral é de Mauro Mendonça Filho. Vale observar como a narrativa irá trabalhar a relação entre as mulheres e o ambiente de luxo carioca. Personagens femininas podem ser complexas sem pedir licença para parecer simpáticas o tempo inteiro. E uma família cheia de segredos costuma precisar de mais do que um grupo silenciado no aplicativo.'],
},
{
 day:14,media:'prima',slug:'adela-prima-pop-internacional',category:'musica',byline:F,kind:'feature',
 title:'ADÉLA estreia com PRIMA e coloca Nicole Kidman no vocabulário do pop',
 excerpt:'O álbum lançado em 4 de setembro vem acompanhado de um clipe que conversa com o cinema. Uma apresentação da novidade internacional do mês.',context:'Álbum de estreia lançado em 4 de setembro pela Capitol Records. Texto de apresentação e contexto; não é uma crítica de audição faixa a faixa.',source:s('Universal Music · anúncio de PRIMA','https://www.universalmusic.ca/2026/09/04/adela-releases-debut-album-prima/'),
 body:['ADÉLA lançou PRIMA, seu álbum de estreia, em 4 de setembro pela Capitol Records. O anúncio também apresenta o videoclipe de Nicole Kidman, dirigido por Hannah Lux Davis. A ligação entre música e cinema aparece de forma explícita: o material oficial destaca referências a papéis da atriz. Para uma artista em apresentação, escolher uma estrela do cinema como título já estabelece uma conversa pop bastante reconhecível.', 'O disco tem Blake Slatkin e Dylan Brady na coprodução executiva. Esses créditos situam a produção, mas não entregam uma avaliação pronta sobre o resultado. Um nome conhecido nos bastidores pode despertar interesse; não deveria funcionar como atalho para chamar um álbum de clássico antes de examiná-lo. A indústria já possui máquinas suficientes para imprimir adjetivos.', 'A pauta internacional desta edição está nessa construção de identidade. Um álbum de estreia precisa apresentar repertório e também comunicar quem pretende ocupar o palco. O clipe escolhe dialogar com um imaginário cinematográfico, oferecendo outra entrada para o público. Referências podem enriquecer uma proposta quando ajudam a contar algo; viram decoração quando existem apenas para serem reconhecidas.', 'PRIMA faz parte dos lançamentos de setembro e pode ser encontrado pelos canais indicados na divulgação oficial. Nossa matéria organiza as informações de lançamento e aponta o tema do vídeo, sem simular uma experiência de escuta que não foi documentada. A curiosidade está aberta. O julgamento musical exige mais trabalho do que ler um press release em voz empolgada.'],
},
{
 day:15,media:'gentlemen',slug:'the-gentlemen-audiencia-netflix-setembro',category:'series-streaming',byline:R,kind:'data',
 title:'The Gentlemen puxa a audiência da Netflix na segunda semana de setembro',
 excerpt:'A segunda temporada aparece em primeiro no Top 10 global de produções em inglês, com 9,9 milhões de visualizações no período de 7 a 13.',context:'Ranking global de TV em língua inglesa da Netflix, semana de 7–13 de setembro de 2026. É um recorte semanal dentro do mês, sem dados de outras plataformas.',source:s('Netflix Tudum · Top 10, semana encerrada em 13 de setembro','https://www.netflix.com/tudum/top10/tv?week=2026-09-13'),
 body:['A segunda temporada de The Gentlemen lidera o Top 10 global de TV em língua inglesa da Netflix na semana de 7 a 13 de setembro. A plataforma informa 9,9 milhões de visualizações e 73,4 milhões de horas assistidas. A primeira temporada também aparece na lista, em terceiro, com 5,5 milhões de visualizações. As duas temporadas estão ocupando a sala — mas não podemos somar seus números como se cada pessoa tivesse enviado documento na entrada.', 'Em segundo lugar, Death of the Pastor’s Wife registra 6 milhões de visualizações. Crew Girl aparece em quarto, com 5,2 milhões. A métrica de visualizações da Netflix é calculada dividindo as horas assistidas pela duração da produção. Ela ajuda a comparar títulos com tempos diferentes; não é uma contagem pública de espectadores únicos.', 'O ranking oferece uma fotografia da segunda semana de setembro. Não estabelece, por si só, qual foi a série mais vista no mês inteiro, no Brasil ou no conjunto de todos os serviços. Produções em outros idiomas são organizadas em outra lista. Uma boa conversa sobre audiência começa por dizer qual televisão, qual semana e qual régua estamos usando.', 'The Gentlemen é o destaque desse recorte. A presença de duas temporadas permite levantar uma hipótese de interesse pelo universo da série, mas a tabela não informa a motivação de cada reprodução. Às vezes o público está maratonando; às vezes está chegando agora. O número revela movimento. O pensamento de quem apertou o play continua sendo assunto privado.'],
},
{
 day:16,media:'accept',slug:'accept-teutonic-titans-cinquenta-anos-metal',category:'musica',byline:F,kind:'feature',
 title:'Accept celebra 50 anos com convidados que dispensam apresentação',
 excerpt:'Teutonic Titans 1976–2026 reúne releituras e participações do universo do metal. O catálogo vira ponto de encontro entre músicos e gerações.',context:'Teutonic Titans 1976–2026 foi lançado em 4 de setembro de 2026 pela Napalm Records. Este texto apresenta o projeto, sem atribuir notas às gravações.',source:s('Napalm Records · Accept e Teutonic Titans','https://label.napalmrecords.com/accept'),
 body:['Accept marca seu cinquentenário com Teutonic Titans 1976–2026, lançado em 4 de setembro pela Napalm Records. O projeto reúne 19 releituras e 50 músicos convidados. Entre os encontros apresentados pela gravadora estão Rob Halford e Matthias Jabs em Balls to the Wall, além de Phil Anselmo, Kirk Hammett e Mikkey Dee em Fast as a Shark. Uma reunião desse tamanho deveria vir com regulamento para o volume do amplificador.', 'A proposta coloca o repertório da banda em circulação por outras vozes e instrumentos. Tobias Forge e Ray Luzier participam de Save Us. A notícia está no formato e nas colaborações, sem precisar transformar a lista de convidados em garantia automática de qualidade. No metal, como em qualquer gênero, um nome de peso não dispensa uma boa execução.', 'O interesse desta coluna é a preservação de um legado em atividade. Regravar pode funcionar como homenagem e também como disputa criativa com o original. Prefiro quando a reverência permite personalidade: copiar cada detalhe seria uma tarefa curiosamente burocrática para um estilo que vende energia. O passado não precisa de um funcionário conferindo carimbos em cada riff.', 'O material oficial identifica o projeto comemorativo e seus participantes. A edição de hoje convida o leitor a conhecer esse encontro com o contexto correto, em vez de fingir uma resenha de audição. Cinquenta anos oferecem história suficiente para uma boa conversa. Para saber o que cada releitura acrescenta, o passo seguinte é ouvir — não aumentar os adjetivos do anúncio.'],
},
{
 day:17,media:'back-future',slug:'de-volta-para-o-futuro-nostalgia-familia',category:'cultura-pop',byline:F,kind:'feature',
 title:'De Volta para o Futuro: o relógio corre, mas a história começa em casa',
 excerpt:'O clássico de 1985 continua oferecendo uma aventura sobre escolhas e consequências. A coluna de nostalgia olha além do DeLorean.',context:'Coluna de nostalgia de 17 de setembro de 2026 sobre o filme original de 1985. Não anuncia uma nova estreia ou um aniversário redondo neste ano.',source:back,
 body:['De Volta para o Futuro continua sendo uma referência fácil de reconhecer: Marty McFly, Doc Brown e um DeLorean transformado em máquina do tempo. Lançado em 1985, o filme dirigido por Robert Zemeckis usa a viagem temporal para colocar o protagonista diante do passado de sua própria família. A ameaça à existência é enorme. O ponto de partida, porém, cabe numa conversa sobre pais, filhos e escolhas.', 'Essa escala humana ajuda a explicar por que a premissa rende mais do que uma coleção de equipamentos excêntricos. A ficção oferece uma pergunta íntima: o que acontece quando alguém descobre que as pessoas responsáveis por sua vida também foram jovens, inseguras e capazes de errar? O passado deixa de ser uma fotografia respeitável e ganha movimento. A família passa a ter história, em vez de existir somente como cenário.', 'É uma leitura que valorizo no clássico. Consequências dão peso à aventura, enquanto o humor evita que cada regra vire uma aula com chamada. Viajar no tempo parece um sonho até o primeiro problema de organização. Já é difícil manter um calendário no presente; levar a reunião para outra década exige uma confiança injustificável na secretaria.', 'A nostalgia desta edição é uma oportunidade para conversar sobre o filme original, sem inventar novidade ou transferir para ele uma estreia de setembro. O DeLorean é a imagem mais vistosa, mas o vínculo entre decisões e responsabilidades oferece assunto duradouro. Uma boa aventura pode brincar com o relógio sem esquecer de perguntar quem terá de arrumar a casa depois.'],
},
{
 day:18,media:'liniker',slug:'liniker-dom-de-iludir-caetano-netflix',category:'musica',byline:R,kind:'feature',
 title:'Liniker leva Dom de Iludir ao teaser da Netflix — e a canção ganha outra cena',
 excerpt:'A cantora regravou a composição de Caetano Veloso para a série brasileira. A novidade coloca a música no centro da apresentação do melodrama.',context:'A regravação foi anunciada com o teaser em 10 de setembro. A fonte não informa lançamento separado de um single ou álbum; a matéria trata de sua presença na produção.',source:netflix,
 body:['A voz de Liniker aparece no teaser de Dom de Iludir, série brasileira da Netflix com Marieta Severo, Alice Wegmann e Nanda Costa. A cantora regravou a composição de Caetano Veloso para essa produção, segundo o anúncio de 10 de setembro. É um encontro entre uma canção já conhecida e uma nova história. A música chegou para apresentar o clima antes de os personagens explicarem seus segredos.', 'O interesse está nessa passagem entre repertório e narrativa. Uma canção inserida em outra obra pode carregar memória para parte do público e funcionar como descoberta para outra. Não é preciso escolher qual ouvinte tem a lembrança mais autorizada. Às vezes a pessoa conhece primeiro a cena, procura a música depois e encontra um universo que nem estava na sua lista de afazeres.', 'O anúncio confirma a participação de Liniker no teaser; não confirma um álbum novo nem dá uma data para um single independente. A distinção parece pequena, mas evita que uma colaboração vire uma promessa que ninguém fez. A internet já tem talento suficiente para montar uma discografia inteira a partir de uma legenda.', 'Nesta pauta de música brasileira, vale observar como uma obra pode ganhar contexto sem perder sua origem. A presença da canção ajuda a apresentar o melodrama anunciado pela Netflix e abre uma conversa entre artistas e públicos. O trecho divulgado é uma porta de entrada, não uma resenha completa da trilha. E portas de entrada são ótimas — especialmente quando têm música em vez de uma senha impossível.'],
},
{
 day:19,media:'macross',slug:'macross-delta-dez-anos-musica-anime',category:'animes-hqs',byline:F,kind:'feature',
 title:'Macross Delta faz dez anos: quando a música também pilota a aventura',
 excerpt:'O projeto comemorativo anunciado em abril recoloca a série de 2016 na conversa. A nostalgia olha para a mistura de palco e ficção científica.',context:'Coluna de nostalgia de 19 de setembro sobre Macross Delta, lançado em 2016. O projeto de dez anos foi anunciado em abril; não é uma confirmação de nova temporada.',source:s('Crunchyroll · projeto de dez anos de Macross Delta','https://www.crunchyroll.com/news/latest/2026/4/3/macross-delta-anime-10th-anniversary-project'),
 body:['Macross Delta completa dez anos em 2026 e recebeu um projeto comemorativo anunciado em abril, com material visual e vídeo de celebração. A série começou em 2016 e pertence a uma franquia que fez da combinação entre ficção científica e música uma marca reconhecível. A pauta de nostalgia de hoje parte dessa identidade: em Macross, o palco não precisa ficar fora da aventura.', 'Esse encontro produz uma pergunta interessante para quem costuma separar histórias de combate e apresentações musicais como se cada uma tivesse de viver num prédio diferente. Uma canção pode organizar vínculos, expressar conflitos e participar do mundo ficcional. O espetáculo então deixa de funcionar somente como intervalo. Passa a ser parte do vocabulário com que a história conversa com o público.', 'A comemoração permite apresentar a obra a quem chegou depois e reorganizar a memória de quem já conhece a série. Não vou chamar material de aniversário de anúncio de temporada: a fonte consultada apresenta um projeto de celebração. Nostalgia merece entusiasmo, mas também merece a diferença entre notícia confirmada e torcida. Um bom fã pode exigir informação antes de sair montando a cabine do robô.', 'Macross Delta oferece um tema para revisitar nessa edição, sem fingir que seu lançamento aconteceu agora. Seu interesse cultural está em mostrar como formatos podem se cruzar. A música tem lugar no espaço, a aventura pode incluir um palco e a ficção científica não precisa pedir desculpas por gostar de um refrão. A fronteira entre gêneros, às vezes, é a parte menos criativa da conversa.'],
},
{
 day:20,media:'control-assist',slug:'control-resonant-assist-mode-acessibilidade',category:'games',byline:F,kind:'feature',
 title:'Control Resonant troca o botão “difícil” por ajustes que fazem diferença',
 excerpt:'O Assist Mode permite alterar componentes do combate separadamente. A tecnologia coloca mais decisões nas mãos de quem joga.',context:'Recursos apresentados pela Remedy em 10 de setembro, antes do lançamento anunciado para 24 de setembro. Texto sobre projeto de acessibilidade, sem testes técnicos próprios.',source:s('Remedy no PlayStation Blog · Assist Mode','https://blog.playstation.com/?p=423069'),
 body:['Control Resonant apresenta um Assist Mode que permite ajustar aspectos do combate separadamente. A Remedy descreve opções para agressividade dos inimigos, janela de esquiva, velocidade de projéteis e dano recebido ou causado. Em vez de escolher apenas um pacote de dificuldade, o jogador pode atuar no componente que está atrapalhando sua experiência. A apresentação foi publicada em 10 de setembro, com lançamento do jogo anunciado para o dia 24.', 'O ponto tecnológico é a separação entre mecânicas. Uma pessoa pode querer manter o desafio estratégico e precisar de mais tempo para reagir. Outra pode preferir priorizar exploração e história. O material oficial também menciona imortalidade e eliminações com um golpe. Essas opções têm finalidades diferentes; tratá-las como uma única resposta simplifica demais o problema que o projeto tenta resolver.', 'Considero uma boa direção oferecer controle sem presumir que todos os jogadores têm as mesmas necessidades. Isso não autoriza declarar que o sistema resolve qualquer barreira: seria necessário avaliar sua implementação e ouvir usuários. O que está confirmado é a proposta apresentada pelo estúdio. A acessibilidade merece critérios melhores do que uma disputa para descobrir quem sofreu mais no tutorial.', 'Esta matéria examina os recursos anunciados, sem inventar medições de desempenho ou uma sessão de testes do SPN. Personalizar uma experiência pode preservar o interesse pela aventura ao mesmo tempo que remove um obstáculo específico. Quando a tecnologia oferece esse tipo de escolha, o botão mais importante talvez seja o que deixa a pessoa continuar. A patrulha do “jogo de verdade” sobreviverá.'],
},
{
 day:21,media:'mars',slug:'perseverance-agua-antiga-marte-jezero',category:'cultura-pop',byline:F,kind:'news',
 title:'Marte guardou uma história de água mais complicada do que parecia',
 excerpt:'Estudo com dados do Perseverance identifica sinais de pelo menos três episódios de contato com água em rochas da cratera Jezero.',context:'Estudo divulgado pelo NASA/JPL em 21 de setembro de 2026. Evidência geológica de água antiga não equivale a detecção de vida.',source:s('NASA/JPL · sistemas de água no Marte antigo','https://www.jpl.nasa.gov/news/nasa-discovery-reveals-complex-water-systems-on-early-mars/'),
 body:['Rochas estudadas pelo Perseverance na cratera Jezero registram sinais de contato com água em pelo menos três ocasiões distintas, segundo pesquisa divulgada pelo NASA/JPL em 21 de setembro. A região, chamada Margin Unit, surpreendeu os cientistas: em vez das rochas sedimentares esperadas junto à margem de um lago antigo, o rover encontrou rochas ígneas. O passado marciano estava organizado de outro jeito.', 'Publicado em Communications Earth & Environment, o estudo usa análises do instrumento SuperCam. O equipamento investiga a composição de alvos rochosos, inclusive com laser, ajudando a reconstruir mudanças preservadas nos minerais. A interpretação apresentada envolve uma sequência complexa de águas subterrâneas, lagos antigos e fluidos hidrotermais. Não é uma fotografia de água correndo hoje; é uma leitura de vestígios geológicos.', 'A notícia merece atenção porque refina a história ambiental de Marte. Também exige uma distinção: encontrar evidências de água não significa encontrar organismos. Condições relacionadas à habitabilidade e demonstração de vida são perguntas diferentes. A curiosidade científica cresce com o resultado, mas os extraterrestres continuam sem entrevista marcada para a redação.', 'O interesse geek pode começar pelas imagens de um rover e terminar numa investigação sobre minerais. É uma boa troca: ficção científica alimenta a imaginação, e pesquisa oferece ferramentas para testar explicações. O novo estudo descreve um passado mais variado do que a expectativa inicial. Quanto mais os dados melhoram, menos espaço sobra para certezas apressadas — inclusive as que já chegaram acompanhadas de uma nave voadora.'],
},
{
 day:22,media:'silent-hill',slug:'silent-hill-townfall-primeira-pessoa-medo',category:'games',byline:A,kind:'feature',
 title:'Silent Hill: Townfall aproxima a câmera — e o medo vem cobrar aluguel',
 excerpt:'A perspectiva em primeira pessoa altera o que o jogador consegue enxergar. O detalhe ajuda a entender por que uma mudança de câmera também muda o terror.',context:'Recursos descritos no PlayStation Blog em 21 de setembro. A matéria comenta a proposta apresentada, sem se passar por análise de uma partida.',source:s('PlayStation Blog · primeira pessoa em Silent Hill: Townfall','https://blog.playstation.com/2026/09/21/silent-hill-townfall-9-ways-first-person-changes-the-iconic-horror-formula/'),
 body:['Silent Hill: Townfall coloca o jogador no ponto de vista de Simon Ordell. A apresentação do PlayStation Blog, publicada em 21 de setembro, explica como a perspectiva em primeira pessoa aproxima o terror e limita a visão do ambiente. A série já experimentou esse tipo de câmera em outros contextos; a novidade aqui está na estrutura desta aventura. Sai um pouco da distância entre você e o personagem. Entra aquela sensação de que o problema bateu diretamente na sua porta.', 'O texto oficial destaca a necessidade de prestar atenção aos lados, ao que está atrás e aos sons. É uma mudança que afeta a forma de buscar informação: enxergar menos pode tornar uma pista sonora mais importante. Uma câmera não é somente o lugar de onde se faz uma fotografia bonita. Nos jogos, ela participa das regras de percepção, decisão e perigo.', 'Essa é a curiosidade geek da edição: parte do medo nasce do que a apresentação deixa fora do alcance. O jogador precisa completar o espaço com atenção e expectativa. A imaginação costuma trabalhar bastante quando não recebeu a planta inteira do imóvel. E, em Silent Hill, ninguém deveria confiar no corretor dizendo que a região é tranquila.', 'A matéria discute a proposta descrita na fonte, sem inventar sustos vividos por nossa equipe. Terror também é projeto: enquadramento, som e tempo de resposta podem mudar a experiência mesmo quando o nome da franquia é conhecido. Aproximar a câmera é aproximar a responsabilidade de olhar. Se a neblina esconder um vizinho inconveniente, pelo menos já sabemos por que não vimos chegando.'],
},
{
 day:23,media:'doom',slug:'dez-piores-adaptacoes-games-cinema',category:'filmes',byline:A,kind:'opinion',
 title:'10 adaptações de games que fazem a gente procurar o botão de reiniciar',
 excerpt:'Uma seleção opinativa das escolhas que mostram como uma marca conhecida não resolve um roteiro. O carinho pelo jogo não vem com imunidade para o filme.',context:'Lista de opinião publicada na edição de 23 de setembro. O recorte são adaptações cinematográficas de games; a ordem é uma seleção do SPN, sem notas ou consenso inventados.',source:s('Rotten Tomatoes · catálogo de adaptações de games','https://editorial.rottentomatoes.com/guide/video-game-movies/'),
 sources:[s('Rotten Tomatoes · filmes de games','https://editorial.rottentomatoes.com/guide/video-game-movies/'),s('Universal Pictures · Doom','https://www.universalpicturesathome.com/movies/doom')],
 body:['Uma adaptação precisa construir um filme, não somente avisar que reconheceu o nome do jogo. Nossa lista dos piores exemplos neste recorte considera a distância entre o potencial de uma marca e a proposta de cinema que ela recebeu. É opinião editorial, não uma contagem de fãs irritados nem uma cópia da ordem do Rotten Tomatoes.', 'O público pode guardar carinho por qualquer um deles. Filme ruim também rende memória boa quando a companhia e a conversa ajudam. Só não vale confundir esse afeto com um certificado obrigatório de qualidade. Abaixo estão dez títulos para discutir — de preferência com senso de humor e sem mandar o controle pela janela.'],
 sections:[
 {title:'1. Alone in the Dark',source:0,paragraphs:['O nome carrega uma promessa de atmosfera que exige muito mais do que uma marca no cartaz. No nosso recorte, simboliza o risco de tratar terror como coleção de ingredientes. Uma adaptação precisa dar motivo para permanecer na sala; reconhecer o título não deveria ser a única tarefa do espectador.']},
 {title:'2. House of the Dead',source:0,paragraphs:['Transformar um jogo de ação em cinema pede outra organização do tempo e do perigo. Fica nesta posição como exemplo da diferença entre uma proposta de arcade e uma narrativa que sustente atenção. O ingresso não vem com pistola de plástico. Alguma coisa precisa ocupar o lugar da participação que existia no jogo.']},
 {title:'3. BloodRayne',source:0,paragraphs:['A personagem oferece uma identidade visual que poderia abrir possibilidades. Nossa avaliação coloca o filme entre os alertas contra depender dessa imagem para carregar toda a obra. Visual reconhecível é uma porta, não a casa pronta. O roteiro também precisa aparecer para trabalhar, mesmo que não fique tão bem no pôster.']},
 {title:'4. Mortal Kombat: Annihilation',source:0,paragraphs:['Uma sequência tem a vantagem de encontrar um público já interessado. Justamente por isso, precisa fazer mais do que aumentar a quantidade de nomes familiares. Entra como lembrança de que escala e coerência não são a mesma coisa. “Mais personagens” é uma resposta possível para uma planilha; para uma história, depende da pergunta.']},
 {title:'5. Street Fighter: The Legend of Chun-Li',source:0,paragraphs:['Focar uma personagem é uma escolha legítima. O problema editorial deste exemplo é o quanto uma origem precisa funcionar sozinha para justificar o universo que anuncia. A marca não deveria pedir ao público que complete a narrativa com suas lembranças do jogo. O manual do controle não é material obrigatório para entender uma sessão.']},
 {title:'6. Double Dragon',source:0,paragraphs:['O título mostra como uma parceria conhecida nos games pode pedir uma adaptação com personalidade própria. Na nossa seleção, a promessa do nome pesa mais do que deveria sobre a conversa a respeito do filme. Irmãos e ação oferecem matéria-prima. Ainda é necessário escolher o que fazer com ela além de imprimir a logo.']},
 {title:'7. Super Mario Bros. (1993)',source:0,paragraphs:['Esta é a versão de 1993, não a animação de 2023. A reinvenção radical do universo torna o filme uma curiosidade e, para o nosso critério de adaptação, um desencontro. Experimentar é permitido. A discussão começa quando o público precisa de um mapa para entender por que o destino tem o nome do lugar que procurava.']},
 {title:'8. Doom (2005)',source:1,paragraphs:['A identidade de Doom é tão forte que a tradução para o cinema exige uma decisão clara sobre o que preservar. Escolhemos o filme como alerta para o peso de uma expectativa emprestada dos jogos. Uma referência visual pode provocar reconhecimento; sustentar a sessão inteira é outro serviço. O demônio mais insistente de Hollywood ainda é o roteiro incompleto.']},
 {title:'9. Hitman: Agent 47',source:0,paragraphs:['Um personagem associado a precisão e planejamento oferece um desafio interessante para cenas e ritmo. Entra por lembrar o risco de transformar uma identidade específica numa embalagem para ação genérica. O terno faz parte da apresentação. A estratégia deveria participar também; caso contrário, a gravata fica responsável por um trabalho muito maior do que suporta.']},
 {title:'10. Far Cry',source:0,paragraphs:['Fecha a seleção como mais um exemplo de que um universo de jogo não se adapta automaticamente. O cinema precisa escolher conflitos, ritmo e ponto de vista próprios. O público pode reconhecer a placa da franquia e ainda perguntar onde está a história. Pelo menos, na sessão de cinema, ninguém precisa instalar uma atualização para sair dos créditos.']},
 ],
},
{
 day:24,media:'luma',slug:'luma-island-anunciado-ps5',category:'games',byline:F,kind:'news',
 title:'Luma Island é anunciado para PS5 com fazenda, exploração e cooperação',
 excerpt:'Feel Free Games confirma a chegada ao console e promete jogo entre plataformas. A data de lançamento ainda não aparece no anúncio.',context:'Anúncio publicado em 24 de setembro de 2026. A lista de desejos abre nessa data; isso não significa que o jogo tenha sido lançado no PS5 no mesmo dia.',source:s('Feel Free Games no PlayStation Blog · Luma Island','https://blog.playstation.com/2026/09/24/luma-island-is-coming-to-ps5'),
 body:['Luma Island vai chegar ao PlayStation 5. A Feel Free Games anunciou a versão em 24 de setembro e informou que os jogadores já podem adicioná-la à lista de desejos. O texto não apresenta uma data de lançamento para o console. A aventura combina construção, cultivo, exploração e os Lumas, companheiros mágicos que participam da jornada. A ilha está recebendo novos interessados; o embarque ainda aguarda calendário.', 'O estúdio descreve partidas individuais ou com até quatro pessoas pela internet, além de suporte a jogo entre PS5, Xbox Series X|S e PC. Há três modos de dificuldade: Cozy, Adventure e Hero. O anúncio também menciona ausência de barra de resistência e de limite de inventário. São características apresentadas pela desenvolvedora, sem uma avaliação técnica do SPN sobre a versão de console.', 'O interesse está na possibilidade de reunir ritmos diferentes. Uma fazenda pode atender quem prefere rotina, enquanto templos e ambientes de exploração oferecem outra direção para a mesma sessão. O resultado depende de como essas atividades se conectam. Uma lista de opções é útil, mas não substitui a experiência de usá-las. Até uma ilha precisa de organização para não virar um depósito de tarefas.', 'A confirmação amplia o público previsto para Luma Island, lançado originalmente no PC em novembro de 2024. Por enquanto, a informação prática é a abertura da lista de desejos e os recursos anunciados. Não há motivo para vender a notícia como estreia consumada. Cultivar expectativa é permitido; colher uma data que ninguém informou, não.'],
},
{
 day:25,media:'ace-combat',slug:'ace-combat-8-narrativa-primeira-pessoa',category:'games',byline:F,kind:'news',
 title:'Ace Combat 8 quer aproximar o piloto da guerra — dentro e fora da cabine',
 excerpt:'A apresentação do PlayStation Blog detalha cenas em primeira pessoa e interações com o esquadrão. O lançamento no PS5 está anunciado para 2 de outubro.',context:'Informações publicadas no PlayStation Blog em 25 de setembro. A matéria atribui a descrição à fonte e não apresenta a experiência como uma partida realizada pelo SPN.',source:s('PlayStation Blog · narrativa de Ace Combat 8','https://blog.playstation.com/2026/09/25/how-ace-combat-8-wings-of-theve-uses-first-person-to-tell-a-more-personal-story/'),
 body:['Ace Combat 8: Wings of Theve aposta em cenas em primeira pessoa para aproximar o jogador de seu protagonista e do esquadrão. A apresentação publicada pelo PlayStation Blog em 25 de setembro descreve pequenas interações durante essas cenas e a importância das conversas pelo rádio. O lançamento para PS5 está anunciado para 2 de outubro. A proposta é levar o conflito além da sequência de missões aéreas.', 'O texto destaca personagens que acompanham o piloto dentro e fora da cabine. Algumas respostas e ações permitem participar de momentos da narrativa, mas a fonte não descreve uma história principal que muda de rumo a cada escolha. Essa diferença importa: interação localizada e uma campanha com ramificações completas não são a mesma promessa. A manchete não precisa acrescentar uma árvore de decisões que o material não anunciou.', 'O ponto mais interessante é dar identidade às pessoas envolvidas na guerra fictícia. Um alvo no radar funciona dentro das regras do jogo; uma voz conhecida no rádio pode acrescentar outra camada à responsabilidade do protagonista. É uma aposta de narrativa. Para avaliar se essa proximidade funciona, seria necessário examinar a campanha, em vez de transformar o anúncio em crítica pronta.', 'A edição de hoje registra a proposta e a data informada pela fonte. Não há medições de desempenho ou relato de sessão própria nesta matéria. Ace Combat tem um universo capaz de oferecer mais do que máquinas vistosas, e o foco no esquadrão pode explorar isso. O avião chama atenção no pôster. Quem está pedindo ajuda pelo rádio é que precisa sustentar a história.'],
},
{
 day:26,media:'redfall',slug:'dez-piores-lancamentos-games-alertas',category:'games',byline:F,kind:'opinion',
 title:'10 lançamentos de games que viraram um aviso para a indústria',
 excerpt:'Uma seleção dos piores tropeços de estreia neste recorte: marcas famosas, promessas grandes e uma diferença incômoda entre anúncio e entrega.',context:'Lista de opinião sobre a recepção e as versões de lançamento. A ordem é editorial, não um ranking estatístico; correções posteriores não são tratadas como inexistentes.',source:s('Metacritic · Big Rigs','https://www.metacritic.com/game/big-rigs-over-the-road-racing/critic-reviews/?platform=pc'),
 sources:[s('Metacritic · Big Rigs','https://www.metacritic.com/game/big-rigs-over-the-road-racing/critic-reviews/?platform=pc'),s('GameSpot · Superman no Nintendo 64','https://www.gamespot.com/reviews/superman-review/1900-2545277/'),s('GameSpot · Ride to Hell','https://www.gamespot.com/reviews/ride-to-hell-retribution-review/1900-6411189/'),s('GameSpot · Sonic the Hedgehog (2006)','https://www.gamespot.com/games/sonic-the-hedgehog-2006/'),s('GameSpot · Aliens: Colonial Marines','https://www.gamespot.com/reviews/aliens-colonial-marines-review/1900-6403683/'),s('Metacritic · Fast & Furious Crossroads','https://www.metacritic.com/game/fast-and-furious-crossroads/'),s('GameSpot · Daikatana para PC','https://www.gamespot.com/reviews/daikatana-review/1900-2580414/'),s('Metacritic · Warcraft III: Reforged','https://www.metacritic.com/game/warcraft-iii-reforged/'),s('Metacritic · Redfall','https://www.metacritic.com/game/redfall/'),s('Metacritic · Balan Wonderworld','https://www.metacritic.com/game/balan-wonderworld/')],
 body:['Um lançamento ruim não precisa reunir todos os defeitos possíveis. Às vezes basta existir uma distância grande demais entre o que uma marca promete e o que seu jogo consegue sustentar. Esta seleção dos piores exemplos no recorte de estreias considera falhas de projeto, execução e expectativa. Não é um levantamento universal, e as posições expressam o critério editorial do SPN.', 'As referências abaixo registram críticas e recepção; nossa ordem e nossos comentários são próprios. Estamos falando da estreia e de sua repercussão, sem fingir uma rodada recente de testes de cada versão. Um patch pode mudar a experiência atual. Não muda retroativamente o que o consumidor recebeu no primeiro dia.'],
 sections:[
 {title:'1. Big Rigs: Over the Road Racing',source:0,paragraphs:['Um jogo de corrida precisa estabelecer regras que façam a competição existir. A recepção crítica de Big Rigs o coloca como caso extremo desse princípio básico. Na nossa ordem, leva o primeiro lugar porque o mínimo funcional pesa mais do que qualquer ambição. O caminhão pode ser enorme; a obrigação de entregar um jogo continua do mesmo tamanho.']},
 {title:'2. Superman no Nintendo 64',source:1,paragraphs:['A crítica contemporânea do GameSpot registra problemas de controle e execução. Para um personagem definido por poderes extraordinários, uma experiência que dificulta as ações básicas representa um desencontro especialmente grande. Como fã da DC, considero um desperdício importante. Kryptonita é parte da história; o controle não precisava concorrer com ela.']},
 {title:'3. Ride to Hell: Retribution',source:2,paragraphs:['A avaliação de lançamento descreve falhas de projeto em várias partes da ação. Este exemplo entra pela soma de escolhas que precisam trabalhar juntas para sustentar uma aventura. Uma premissa barulhenta não resolve a estrutura. Até a rebeldia precisa de direção — principalmente quando o jogador está tentando entender por que deveria continuar a viagem.']},
 {title:'4. Sonic the Hedgehog (2006)',source:3,paragraphs:['A recepção da edição de 2006 serve de alerta para uma série que depende de movimento. Quando execução e ritmo brigam, a identidade do personagem fica no meio. Não estamos condenando a franquia inteira nem suas outras versões. O problema é essa estreia. Velocidade deveria levar à diversão, não à necessidade de explicar o que falhou pelo caminho.']},
 {title:'5. Aliens: Colonial Marines',source:4,paragraphs:['A crítica do GameSpot aponta ação pouco marcante e inimigos que não sustentam o terror esperado. O contraste com o potencial de Alien pesa na seleção. Reconhecer um monstro não basta para sentir ameaça. A tensão precisa funcionar nas regras e no comportamento; uma criatura famosa ainda tem de comparecer ao próprio serviço.']},
 {title:'6. Fast & Furious Crossroads',source:5,paragraphs:['A recepção reunida pelo Metacritic ajuda a situar um lançamento que encontrou pouco entusiasmo crítico. O exemplo lembra o risco de uma licença conhecida ocupar o lugar de uma proposta convincente. O cinema da franquia vende exagero com identidade. Um jogo precisa transformar essa energia em participação, em vez de pedir que a logo faça todas as curvas.']},
 {title:'7. Daikatana para PC',source:6,paragraphs:['A avaliação original permite discutir o peso de uma expectativa grande sobre uma execução desigual. Entra como aviso contra confundir ambição com resultado. A história de um projeto pode ser fascinante, mas o comprador recebe um jogo, não a biografia da promessa. Marketing não serve de munição quando a fase começa.']},
 {title:'8. Warcraft III: Reforged',source:7,paragraphs:['Uma remasterização trabalha com a memória de um público que já conhece a obra. Essa responsabilidade aumenta a importância de explicar e entregar o que mudou. A recepção da estreia torna Reforged um caso útil para essa discussão. Reformar uma casa querida exige cuidado: o proprietário costuma notar quando a novidade aparece antes da organização.']},
 {title:'9. Redfall',source:8,paragraphs:['As avaliações de lançamento foram divididas, com críticas relevantes à execução e à proposta. O colocamos entre os alertas porque uma ideia de aventura cooperativa precisa sustentar interesse além de sua apresentação. Vampiros oferecem identidade, mas não completam sozinhos o projeto. Quem esconde o sol ainda tem de iluminar os motivos para o público permanecer.']},
 {title:'10. Balan Wonderworld',source:9,paragraphs:['Fecha o recorte como lembrança da diferença entre um visual cheio de personalidade e uma experiência convincente. Sua recepção crítica permite discutir essa distância sem negar a existência de quem gostou. O espetáculo começa no convite, mas precisa continuar quando a pessoa assume o controle. Um palco bonito não deveria encerrar o trabalho antes da primeira cena.']},
 ],
},
{
 day:27,media:'madonna',slug:'madonna-abertura-vma-2026',category:'famosos',byline:R,kind:'news',
 title:'Madonna está escalada para abrir o VMA 2026 — o palco já tem assunto',
 excerpt:'O anúncio oficial coloca a cantora na abertura da cerimônia de 27 de setembro. A volta lembra como o VMA ajuda a construir a memória das estrelas.',context:'Prévia da cerimônia marcada para 27 de setembro em Los Angeles. Baseada no anúncio de Madonna; não antecipa vencedores ou apresenta uma performance como já realizada.',source:s('Madonna · anúncio da abertura do VMA 2026','https://www.madonna.com/blogs/news/madonna-to-open-the-2026-video-music-awards'),
 body:['Madonna foi anunciada para abrir o MTV Video Music Awards de 2026, marcado para 27 de setembro no Peacock Theater, em Los Angeles. A confirmação aparece em seu site oficial. É um convite que coloca a cantora novamente no centro de uma cerimônia ligada à apresentação de imagens, performances e personagens pop. Antes de qualquer troféu ser entregue, a abertura já oferece um assunto.', 'O material divulgado apresenta a participação como a primeira performance ao vivo de Madonna no VMA em 23 anos. A referência ao tempo passado ajuda a dimensionar a expectativa, mas não conta antecipadamente como será o número. Uma prévia deve separar o compromisso confirmado do espetáculo que ainda precisa acontecer. Nem toda ansiedade precisa vestir uma fantasia de informação exclusiva.', 'Para a pauta de famosos, interessa observar como uma artista reconhecida atravessa diferentes públicos. Premiações podem reintroduzir nomes, reorganizar lembranças e colocar gerações na mesma conversa. A Madonna que alguém conhece por um vídeo antigo pode aparecer no mesmo feed de quem chegou por outro repertório. A memória pop vive fazendo essas festas em que ninguém combinou a lista de convidados.', 'Esta matéria registra o anúncio de abertura, sem antecipar vencedores ou descrever bastidores não informados. Depois da cerimônia, apresentações e resultados precisam de confirmação própria. Por enquanto, há uma presença oficial e um palco com história suficiente para despertar curiosidade. O vestido da expectativa está pronto; o jornalismo ainda precisa conferir o que aconteceu antes de anunciar o fim da festa.'],
},
{
 day:28,media:'prada',slug:'prada-verao-2027-saias-moda',category:'cultura-pop',byline:R,kind:'news',
 title:'Prada coloca a saia no centro do verão 2027 e transforma detalhe em conversa',
 excerpt:'Miuccia Prada e Raf Simons trabalham variações de uma mesma peça. A apresentação oficial explora materiais, estrutura e formas de vestir.',context:'Coleção feminina primavera/verão 2027 apresentada pela Prada em setembro de 2026. A análise se baseia no material da marca; não é publicidade nem avaliação de compra.',source:s('Prada · coleção feminina SS 2027','https://www.prada.com/au/en/pradasphere/fashion-shows/2027/ss-womenswear.html'),
 body:['A coleção feminina primavera/verão 2027 da Prada coloca a saia no centro da proposta de Miuccia Prada e Raf Simons. A apresentação oficial descreve variações dentro de uma silhueta gráfica definida, com mudanças de materiais, camadas e elementos de acabamento. A peça não entra somente como parte de um look: vira o objeto em torno do qual a coleção organiza suas perguntas.', 'Entre os detalhes descritos estão bordados de cristais, fechos, tecidos e estruturas visíveis. A combinação permite discutir o que normalmente fica escondido e o que passa a participar da aparência. A notícia de moda não depende de decretar que todo mundo vai usar a mesma coisa no verão. Uma passarela pode funcionar como pesquisa visual antes de chegar, ou não, ao guarda-roupa cotidiano.', 'O interessante dessa proposta é a concentração. Em vez de trocar de assunto a cada conjunto, a coleção retorna a uma peça e explora diferenças. Isso abre espaço para olhar além da primeira impressão. Às vezes o detalhe que parece discreto muda a leitura inteira. A saia está no centro, mas os coadjuvantes claramente pediram atualização no contrato.', 'Nossa leitura parte das imagens e do texto oficial da Prada, sem relatar presença no desfile ou recomendar uma compra. Moda participa da cultura pop porque produz imagens que circulam, recebem interpretações e ganham outros usos. A conversa pode ser sobre forma, memória e expressão. Não precisa começar e terminar com uma etiqueta de preço — até porque o senso crítico não deveria ser vendido como acessório.'],
},
{
 day:29,media:'control-art',slug:'control-resonant-manhattan-arte-chefes',category:'games',byline:F,kind:'news',
 title:'Control Resonant mostra como transformou Manhattan em um lugar inquietante',
 excerpt:'Em entrevista ao PlayStation Blog, profissionais da Remedy explicam as escolhas de arte, cenário e tecnologia por trás da cidade e dos chefes.',context:'Entrevista publicada pelo PlayStation Blog em 29 de setembro. As declarações vêm dessa publicação, não de uma entrevista realizada pelo SPN.',source:s('PlayStation Blog · arte e tecnologia de Control Resonant','https://blog.playstation.com/2026/09/29/how-control-resonants-art-design-and-tech-shaped-its-bosses-paranaturally-twisted-manhattan-and-more/'),
 body:['A Remedy apresentou ao PlayStation Blog parte do trabalho que transformou Manhattan no cenário de Control Resonant. A entrevista publicada em 29 de setembro reúne a designer de fases Anne-Marie Grönroos, o diretor de arte Elmeri Raitanen e o designer de gameplay Sergey Mohov. Eles descrevem relações entre personagens, ambiente, chefes e tecnologia. A cidade aparece como uma interpretação ficcional, não como uma reprodução literal da Nova York atual.', 'O material destaca uma Manhattan com identidade retro e elementos que participam da estranheza do mundo. O movimento de Dylan também comunica algo sobre seu estado e seus poderes. O objetivo discutido é conectar o projeto visual à experiência, em vez de usar o cenário como papel de parede. Chefes e destruição entram nessa construção coletiva de uma realidade que perdeu parte de suas regras.', 'Esse tipo de bastidor interessa porque torna visível o trabalho entre áreas. Um personagem precisa existir como ideia, imagem, movimento e ação. Se cada parte falar uma língua completamente diferente, o jogador receberá uma apresentação sofisticada e uma experiência confusa. A coerência não pede ausência de estranheza; pede que a estranheza tenha uma função. Até uma cidade paranatural precisa saber por que está daquele jeito.', 'A fonte é a entrevista conduzida pelo PlayStation Blog. O SPN organiza seus pontos e acrescenta uma leitura editorial, sem simular contato próprio com o estúdio ou testes de desempenho. A novidade desta edição é a explicação do processo. O resultado pode ser discutido por seus critérios; o fato de Manhattan estar inquietante não significa que a nossa apuração também precise abandonar a ordem.'],
},
{
 day:30,media:'jojo',slug:'setembro-animes-mangas-audiencia-vendas-japao',category:'animes-hqs',byline:A,kind:'data',
 title:'Setembro geek em números: Sazae-san na TV e The JOJOLands nas livrarias',
 excerpt:'Dois recortes japoneses mostram audiência de anime e vendas de mangá. São semanas específicas, com unidades diferentes — e nenhum campeão mundial inventado.',context:'TV japonesa: semana de 7–13 de setembro. Mangás físicos no Japão: 14–20 de setembro, ranking Oricon datado de 28 de setembro. Não há nesta matéria um fechamento mensal completo ou ranking brasileiro de HQs.',source:s('Video Research · audiência televisiva japonesa','https://www.videor.co.jp/audience/'),
 sources:[s('Video Research · semana de 7–13 de setembro, consultada em 1 de outubro','https://www.videor.co.jp/audience/'),s('Oricon · mangás, 14–20 de setembro','https://www.oricon.co.jp/rank/obc/w/2026-09-28/'),s('Oricon Group · volumes e estimativas de vendas','https://www.oricon-group.com/news/9307/')],
 body:['O fim de setembro pede números, mas pede também uma régua que não misture coisas diferentes. Nos recortes consultados, Sazae-san lidera a seção de anime da audiência televisiva japonesa, enquanto o volume 9 de The JOJOLands aparece em primeiro nas vendas semanais de mangás físicos da Oricon. Não é uma disputa entre desenho e papel. Cada tabela mede uma coisa; juntar tudo seria fazer um campeonato de futebol com placar de receita de bolo.', 'Na semana de 7 a 13 de setembro, a Video Research informa audiência média estimada de 7,343 milhões de pessoas para Sazae-san. Chibi Maruko-chan aparece com 4,704 milhões e Detective Conan com 4,474 milhões. Os dados se referem às exibições e à cobertura televisiva indicada pela empresa. Não são reproduções de streaming, espectadores únicos do mês nem uma estimativa global do público desses animes.', 'Nas vendas físicas estimadas de mangás no Japão, entre 14 e 20 de setembro, a Oricon registra 54.642 exemplares para The JOJOLands, volume 9. Onna no Sono no Hoshi, volume 5, vem depois com 39.144, seguida por Uruwashi no Yoi no Tsuki, volume 11, com 36.210. A tabela publicada com data de 28 de setembro representa essa semana de medição, não todas as compras feitas durante o mês.', 'Esses resultados ajudam a observar setembro, mas não autorizam anunciar os mais assistidos ou vendidos do mês inteiro. Também não cobrem o mercado brasileiro nem todas as HQs internacionais. Para esse fechamento, seria necessário reunir bases mensais compatíveis. Preferimos publicar os recortes verificáveis a preencher a lacuna com um número que nasceu bonito e sem documento.', 'O retrato disponível combina obras consolidadas da televisão e volumes recentes nas livrarias. É uma conversa interessante sobre continuidade e movimento, com alcance limitado pelas fontes. Quem quiser discutir o tamanho de um fandom agora sabe qual dado está na mesa. O entusiasmo pode crescer livremente; o total precisa continuar cabendo na conta.'],
},
];
